<?php
declare(strict_types=1);
namespace App\Controllers; use App\Core\Request;use App\Core\View;use App\Core\Session;use App\Middleware\PermissionMiddleware;use App\Services\ReportService;use App\Repositories\CategoryRepository;use App\Repositories\AccountRepository;
final class ReportController { public function index(Request $r):void{PermissionMiddleware::require('reports.view');$f=$r->all();$rows=(new ReportService())->expenses($f,(int)Session::get('user_id'));$categories=(new CategoryRepository())->all();$accounts=(new AccountRepository())->all();View::render('reports/index',compact('rows','f','categories','accounts'));} public function csv(Request $r):void{PermissionMiddleware::require('reports.export');$rows=(new ReportService())->expenses($r->all(),(int)Session::get('user_id'));header('Content-Type: text/csv');header('Content-Disposition: attachment; filename="expense-report.csv"');$out=fopen('php://output','w');fputcsv($out,['Date','Amount','Category','Account','Description']);foreach($rows as $row)fputcsv($out,[$row['expense_date'],$row['amount'],$row['category'],$row['account'],$row['description']]);fclose($out);exit;}}
